function trendModal(trendId){let t=allTrends().find(x=>x.id===trendId);if(!t)return;openModal(t.title,`<div class="modal-copy">${platformTag(t.platform)} <span class="tag">${esc(t.category)} · 待验证 / To test</span><p>${esc(t.detail||t.summary)}</p><h3>可以尝试的实验</h3><p>${esc(t.hypothesis)}</p><h3>审核关注点</h3><ul>${(t.checks||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>原始参考</h3><a href="${esc(safeURL(t.url))}" target="_blank" rel="noopener noreferrer">${esc(t.source)} ↗</a><p class="source-note">${t.addedAt?'收藏日期：'+esc(t.addedAt)+'。':''}来源提供背景参考，不代表认可当前假设。请核对来源当前内容与适用范围。</p></div><div class="form-actions"><button class="secondary" id="saveTrend">${data.bookmarks.includes(t.id)?'取消收藏':'收藏参考'}</button><button class="primary" id="trendToExperiment">转为设计实验 ${icon('arrow')}</button></div>`);$('#saveTrend').onclick=()=>{toggleBookmark(t.id);trendModal(t.id)};$('#trendToExperiment').onclick=()=>experimentModal(null,{title:t.title+' · 验证',platform:t.platform,category:t.category,notes:t.hypothesis+'\n参考：'+t.url,prompt:t.detail||t.summary})}
